cat > CorporatePlan.java <<'EOF'
package pousada.plan;

import pousada.PousadaException;
import pousada.Stay;

import java.math.BigDecimal;
import java.util.Map;

public class CorporatePlan extends DiscountedPlan {
    private static final Map<String, String> DISCOUNT_BY_COMPANY = Map.of(
            "TECNOSUL", "0.12",
            "AGROVALE", "0.18",
            "FARMAVIDA", "0.25");

    public String code() { return "CORPORATE"; }

    @Override
    public void validate(Stay stay) {
        if (stay.companyCode() == null || !DISCOUNT_BY_COMPANY.containsKey(stay.companyCode())) {
            throw PousadaException.invalid("O plano CORPORATE exige o código de uma empresa conveniada");
        }
    }

    protected String discountFraction(Stay stay) { return DISCOUNT_BY_COMPANY.get(stay.companyCode()); }

    public BigDecimal refund(BigDecimal amountPaid) { return amountPaid; }
}
EOF
cat > WeekendPackagePlan.java <<'EOF'
package pousada.plan;

import pousada.Money;
import pousada.PousadaException;
import pousada.Quote;
import pousada.RoomType;
import pousada.Stay;

import java.math.BigDecimal;
import java.time.DayOfWeek;
import java.util.Map;

public class WeekendPackagePlan implements RatePlan {
    private static final Map<RoomType, BigDecimal> PRICE = Map.of(
            RoomType.STANDARD, Money.of("520.00"),
            RoomType.DELUXE, Money.of("820.00"),
            RoomType.SUITE, Money.of("1200.00"));

    public String code() { return "WEEKEND_PACKAGE"; }

    @Override
    public void validate(Stay stay) {
        if (stay.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY || stay.nights() != 2) {
            throw PousadaException.invalid("O WEEKEND_PACKAGE exige entrada na sexta e saída no domingo seguinte");
        }
    }

    @Override
    public Quote quote(Stay stay) {
        return new Quote(stay.nights(), PRICE.get(stay.room().type()), Money.ZERO);
    }

    public BigDecimal refund(BigDecimal amountPaid) { return Money.fraction(amountPaid, "0.5"); }
}
EOF
cat > RatePlans.java <<'EOF'
package pousada.plan;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;

/** The only place that knows which rate plans exist. A new plan is one class and one line here. */
public final class RatePlans {
    private static final Map<String, RatePlan> BY_CODE = new LinkedHashMap<>();

    static {
        register(new StandardPlan());
        register(new NonRefundablePlan());
        register(new CorporatePlan());
        register(new WeekendPackagePlan());
        register(new LongStayPlan());
    }

    private RatePlans() {}

    private static void register(RatePlan plan) {
        BY_CODE.put(plan.code(), plan);
    }

    public static Optional<RatePlan> find(String code) {
        return Optional.ofNullable(BY_CODE.get(code));
    }
}
EOF

